/** A02-R01-REG-SAL: un registro por contrato y grupo de conceptos de saldo. */
public record SaldoContrato(
        int sistema,                 // A02-R01-SIS  9(04) COMP, ej. 0500
        int producto,                // A02-R01-PRD  9(04) COMP
        int instrumento,             // A02-R01-INS  9(04) COMP
        String cuenta,               // A02-R01-CTA  9(20) COMP: String para no perder ceros
        int sucursalProceso,         // A02-R01-SUCPRO (REDEFINES de CTA)
        String contrato,             // A02-R01-CNT  9(16): P172 lo compara con 11 dígitos
        EstadoCuenta edoCta,         // A02-R01-EDOCTA 9(02)
        LocalDate fecProceso,        // FECPRO 9(08) desde la renovación Cronos 2000
        LocalDate fecIniCorte, LocalDate fecFinCorte, LocalDate fecUltMov,
        boolean continua,            // A02-R01-STATUS: 00 último, 01 sigue otro registro
        List<ConceptoSaldo> conceptos) {

    public record ConceptoSaldo(int clave,            // A02-R01-CVESDO, 0002 = saldo actual
                                BigDecimal importe) {} // S9(13)V99 COMP -> escala 2, con signo

    public static final int SALDO_ACTUAL = 2;

    public SaldoContrato {
        if (edoCta.generaEstado() && (fecIniCorte == null || fecFinCorte == null)) {
            throw new IllegalArgumentException("EDOCTA > 0 exige FECINI y FECFIN");
        }
    }
}

public enum EstadoCuenta {
    SOLO_SALDOS(0, false), ACTIVO(1, true), CANCELADO_EN_MES(2, true),
    INACTIVO_GENERA(3, true), INACTIVO_NO_GENERA(4, false);
    private final int codigo; private final boolean genera;
    EstadoCuenta(int c, boolean g) { codigo = c; genera = g; }
    public boolean generaEstado() { return genera; }
}

/** Interfaz IntelliMatch. Mismo ancho (197) para encabezado y detalle. */
public sealed interface IntelliMatchRecord permits IntelliMatchRecord.Encabezado, IntelliMatchRecord.Detalle {

    String toFixed();   // registro posicional tal como lo espera IntelliMatch

    /** A00-R00-HDR-INTE: saldo de apertura y cierre por cuenta. */
    record Encabezado(String numCta,                  // X(34)
                      LocalDate fecApertura, LocalDate fecCierre,   // 9(06) AAMMDD
                      char natApertura, BigDecimal sdoApertura,     // 9(14)V99 sin signo
                      char natCierre, BigDecimal sdoCierre) implements IntelliMatchRecord {
        public String toFixed() {
            return "HS" + Fixed.x(numCta, 34) + "S" + "0".repeat(9)
                 + Fixed.aammdd(fecApertura) + Fixed.aammdd(fecCierre)
                 + natApertura + Fixed.importe(sdoApertura, 14, 2) + "F"
                 + natCierre  + Fixed.importe(sdoCierre, 14, 2)  + "F"
                 + " ".repeat(103);
        }
    }

    /** A00-R01-INTE-REGMOV: un movimiento. */
    record Detalle(String numCta, LocalDate fecConta, LocalDate fecValor, String tipo,
                   char naturaleza, BigDecimal importe, String referen, String surefer,
                   String otraref, String detalle, int sistema, int clave) implements IntelliMatchRecord {
        public String toFixed() {
            return "D" + Fixed.x(numCta, 35) + Fixed.aammdd(fecConta) + Fixed.aammdd(fecValor)
                 + Fixed.x(tipo, 2) + naturaleza + Fixed.importe(importe, 14, 2)
                 + Fixed.x(referen, 16) + Fixed.x(surefer, 16) + Fixed.x(otraref, 16)
                 + Fixed.x(detalle, 40) + " ".repeat(34) + Fixed.n(sistema, 4) + Fixed.n(clave, 4);
        }
    }
}

/** Fixed.importe: valor absoluto, escala 2 sin punto; el signo viaja en la naturaleza. */

