public record CuentaIntelliMatch(String cuenta,      // WKS-INTEL-CUENTA 9(11)
                                 String contrato,    // WKS-INTEL-CTO    9(11)
                                 int archivo) {}     // WKS-INTEL-ARCHIVO: número de archivo E01

/** Estado por corrida que en COBOL vive en los mismos 27 bytes de la tabla. */
public final class EstadoCuenta172 {
    boolean tuvoMovimientos;    // WKS-INTEL-INDMOV
    boolean resideEnCsi;        // WKS-INTEL-RESIDE
    BigDecimal sdoIniDia = BigDecimal.ZERO.setScale(2);   // WKS-SDO-INI-DIA  S9(14)V99
    BigDecimal sdoFinDia = BigDecimal.ZERO.setScale(2);   // WKS-SDO-FIN-DIA
    BigDecimal sdoCalculado = BigDecimal.ZERO.setScale(2);
}

@Configuration
@EnableConfigurationProperties(P172Properties.class)
public class InterfazIntelliMatchConfig {

    /** 00000-INICIO. El parámetro W77-SISTEMA-PARAMETRO llega como job parameter. */
    @Bean
    Job interfazIntelliMatch(JobRepository repo, Step verificaB05, Step cargaCatalogos,
                             Step seleccionaMovimientos, Step ordenaMovimientos,
                             Step seleccionaSaldos, Step generaArchivos, Step generaFaltantes,
                             Step uneArchivos, Step enviaIntelliMatch, Step actualizaB05,
                             EsCsiConcentradorDecider csi) {
        return new JobBuilder("S151P172", repo)
                .start(verificaB05)                 // alta disponibilidad: solo si WKS-VALUE = 0
                .next(cargaCatalogos)               // S080 con llave 500 y luego 408
                .next(seleccionaMovimientos).next(ordenaMovimientos)
                .next(seleccionaSaldos).next(generaArchivos).next(generaFaltantes)
                .next(csi).on("CONCENTRADOR").to(uneArchivos).next(enviaIntelliMatch).next(actualizaB05)
                .from(csi).on("*").to(actualizaB05)
                .end().build();
    }
}

/** IF WKS-NUMCSI = 10: el número de CSI concentrador pasa a configuración. */
@Component
@RequiredArgsConstructor
class EsCsiConcentradorDecider implements JobExecutionDecider {
    private final P172Properties props;      // p172.csi-concentrador: 10
    private final ContextoCsi contexto;
    public FlowExecutionStatus decide(JobExecution j, StepExecution s) {
        return contexto.numeroCsi() == props.csiConcentrador()
                ? new FlowExecutionStatus("CONCENTRADOR") : FlowExecutionStatus.COMPLETED;
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class SeleccionMovimientos500 implements ItemProcessor<MovimientoLog, List<MovimientoTrabajo>> {

    private static final Set<Integer> ORIGENES = Set.of(1, 3);
    private final P172Properties props;        // p172.tipos-proceso-excluidos: [40, 41, 42, 43] (Teletón)
    private final GeneradorGce gce;
    private final SelectorCuentas selector;

    /** 03-301-10-ELIGE-MOVS-500. La función 99 marca el fin lógico del LOG151. */
    @Override
    public List<MovimientoTrabajo> process(MovimientoLog m) {
        if (m.funcion() == 99) {
            throw new FinDeLogException();          // el reader corta aquí (W77-FIN = 1)
        }
        if (!ORIGENES.contains(m.origen())
                || props.tiposProcesoExcluidos().contains(m.tipoProceso())) {
            return null;
        }
        m.claves().stream()                         // hasta 5 claves; la primera en 0 corta
                .takeWhile(c -> c.cveTran() != 0)
                .forEach(c -> gce.evalua(m, c));   // 03-302-10-VALIDA-CLAVE
        return selector.revisa(m, 500);             // 03-303-11-REVISA-MOVTO con W77-IND = 1
    }
}

/** 03-301-22-GRABA-REGISTRO: naturaleza del movimiento hacia IntelliMatch. */
static char naturalezaIntelliMatch(int sistemaLog, ParametroTransaccion p) {
    if (sistemaLog != 500) {
        return 'D';                                // cualquier otro sistema: cargo
    }
    if (p.natAlfa() == 1) return 'D';
    if (p.natAlfa() == 2) return 'C';
    return (p.natS028() == 1) ? 'D' : 'C';         // ALFA sin definir: decide S028
}

static MovimientoTrabajo aTrabajo(MovimientoLog m, ClaveImporte c, ParametroTransaccion p) {
    // A00-R01-IMPORTE es 9(16)V99 y A02-MOV-IMPORTE 9(14)V99: el MOVE pierde los dos dígitos altos.
    BigDecimal importe = Fixed.cabeEn(c.importe(), 14, 2);   // falla en vez de truncar
    return new MovimientoTrabajo(m.sucursal(), m.cuenta(), m.fecMov(), m.horMov(),
            m.fecCont(), m.fecVal(), naturalezaIntelliMatch(m.sistema(), p), importe,
            m.autoriza(), m.referencia());
}

@Component
@RequiredArgsConstructor
public class GeneradorGce {

    private final P172Properties props;      // p172.gce.claves: [1248,1249,1251,1253,1256,1257,2499,2500,2502,2504,2507,2508]
    private final CatalogoTransacciones catalogo;
    private final ItemWriter<IntelliMatchRecord.Detalle> movGceWriter;   // A03-MOV-GCE

    /** 03-302-10-VALIDA-CLAVE. */
    public void evalua(MovimientoLog m, ClaveImporte c) {
        ParametroTransaccion p = catalogo.de500(c.cveTran());
        boolean esGce = p.gce() == 3
                && m.moneda() == props.gce().moneda()                  // 5
                && (p.natAlfa() == 1 || p.natAlfa() == 2)
                && (p.natS028() == 1 || p.natS028() == 2)
                && props.gce().claves().contains(c.cveTran());
        if (esGce) {
            movGceWriter.write(Chunk.of(registroGce(m, c, p)));      // 03-301-30-GRABA-REG-GCE
        }
    }

    /** La naturaleza GCE es la contraria a la de IntelliMatch para el mismo catálogo. */
    static char naturalezaGce(int sistemaLog, ParametroTransaccion p) {
        if (sistemaLog != 500) return 'C';
        if (p.natAlfa() == 1) return 'C';
        if (p.natAlfa() == 2) return 'D';
        return (p.natS028() == 1) ? 'C' : 'D';
    }

    private IntelliMatchRecord.Detalle registroGce(MovimientoLog m, ClaveImporte c, ParametroTransaccion p) {
        return new IntelliMatchRecord.Detalle(props.gce().cuenta(),   // "158224" compilado
                m.fecCont(), m.fecVal() == null ? m.fecCont() : m.fecVal(), "OP",
                naturalezaGce(m.sistema(), p), c.importe(), m.cuentaIntelli(),
                m.motivoDevolucion(), "", "", m.sistema(), c.cveTran());
    }
}

/** 03-303-14-BUSCA-SDOFIN: el saldo de cierre es el concepto 0002 (saldo actual). */
static Optional<BigDecimal> saldoCierre(SaldoContrato s) {
    return s.conceptos().stream()
            .filter(c -> c.clave() == SaldoContrato.SALDO_ACTUAL)
            .map(SaldoContrato.ConceptoSaldo::importe)
            .findFirst();                                   // sin concepto 0002: cero
}

/** 03-303-20-TRAE-SDO-INICIO: CALL S500L020SDOINIDIA con reintento. */
@Component
@RequiredArgsConstructor
class SaldoInicioDiaClient {

    private final SaldosS500Api s500;          // reemplaza la librería S500L020SDOS
    private final AvisoOperador avisos;        // CALL "LJ IN LIB-DISP"

    @Retryable(retryFor = S500OcupadoException.class,          // resultados 5 y 17
               maxAttempts = 8, backoff = @Backoff(delay = 30_000))
    BigDecimal saldoInicio(String contrato, LocalDate fechaProceso) {
        SaldoInicioDia r = s500.saldoInicioDia(contrato, fechaProceso);
        return r.saldo500().subtract(r.saldo408());           // O-500-SDO-INIDIA - O-408-SDO-INIDIA
    }

    @Recover
    BigDecimal agotado(S500OcupadoException e, String contrato, LocalDate fecha) {
        avisos.operador("020901", " ERROR : %s NO CONTESTA LIB. S500L020 FAVOR DE VERIFICAR "
                .formatted(e.resultado()));
        throw new ProcesoAbortadoException(e);   // decisión de diseño: el COBOL reinicia el contador
    }
}

/** 03-304-10-LEE-MOV: corte de control por archivo y cuenta sobre A02-MOVS151 ordenado. */
@Component
@StepScope
@RequiredArgsConstructor
public class GeneradorIntelliMatchProcessor implements ItemProcessor<MovimientoTrabajo, List<IntelliMatchRecord>> {

    private final Map<String, EstadoCuenta172> estado;   // por cuenta IntelliMatch
    private LlaveCuenta anterior;                          // WKS-LLAVE-ANT
    private BigDecimal saldo = BigDecimal.ZERO.setScale(2); // W77-SALDO S9(14)V99

    @Override
    public List<IntelliMatchRecord> process(MovimientoTrabajo m) {
        if (m.llave().equals(anterior)) {
            anterior = m.llave();
            return List.of(detalle(m));           // misma cuenta: solo detalle
        }
        anterior = m.llave();
        saldo = BigDecimal.ZERO.setScale(2);
        return iniciaCuenta(m);                   // encabezado HS + primer detalle (03-304-18)
    }

    /** 03-304-12-CALCULA-SALDO: cargo resta, abono suma; otro valor no mueve el saldo. */
    private IntelliMatchRecord.Detalle detalle(MovimientoTrabajo m) {
        saldo = switch (m.naturaleza()) {
            case 'D' -> saldo.subtract(m.importe());
            case 'C' -> saldo.add(m.importe());
            default  -> saldo;
        };
        estado.get(m.cuenta()).sdoCalculado = saldo;   // WKS-SDO-CALCULADO
        return Detalles.de(m);                           // 03-304-14-ESCRIBE-REG-DETALLE
    }
}

@Configuration
public class EnvioIntelliMatchFlowConfig {

    /** 05-500-00-ENVIA-ARCHIVOS + 05-500-10-SEND-INTELAR. */
    @Bean
    IntegrationFlow envioIntelliMatch(SessionFactory<SftpClient.DirEntry> intelliMatchSftp,
                                      P172Properties props, AvisoOperador avisos) {
        return IntegrationFlow.from("archivosIntelliMatchUnificados")   // un mensaje por E02 cerrado
                .handle(Sftp.outboundAdapter(intelliMatchSftp, FileExistsMode.FAIL)
                                .remoteDirectory(props.intellimatch().directorio())
                                .useTemporaryFileName(true),
                        e -> e.advice(new RequestHandlerRetryAdvice()))
                .get();
    }

    /** INTELARSND devolvía W77-INTE-SNT <> 0; hoy solo se avisa al operador. */
    @Bean
    IntegrationFlow erroresEnvio(AvisoOperador avisos) {
        return IntegrationFlow.from("errorChannel")
                .handle(ErrorMessage.class, (err, h) -> {
                    avisos.error("020901", "ERROR EN EL ENVIO DEL ARCHIVO %s A INTELLIMATCH"
                            .formatted(err.getOriginalMessage().getHeaders().get(FileHeaders.FILENAME)));
                    return null;     // igual que el COBOL: el job no se marca en falla
                })
                .get();
    }
}
